#!/usr/bin/env python3
"""Render the separate, amended J0643 failed-model displacement diagnostic."""
from pathlib import Path
import json,hashlib
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];F=ROOT/'results/archive_complete/J064326-504112/failure_pair'
def load(p):return json.loads(p.read_text())
def main():
 s=load(F/'summary.json');n=load(F/s['null_relative_path']);a=load(F/s['alternative_relative_path']);nd=np.load((F/s['null_relative_path']).with_suffix('.npz'));ad=np.load((F/s['alternative_relative_path']).with_suffix('.npz'))
 fig,axes=plt.subplots(4,2,figsize=(13,11),gridspec_kw={'width_ratios':[2,1]})
 for row,k in enumerate(n['configuration']['lines']):
  v=nd[f'{k}_v'];flux=nd[f'{k}_flux'];err=nd[f'{k}_error'];good=nd[f'{k}_good'];nm=nd[f'{k}_model'];am=ad[f'{k}_model'];ax,rx=axes[row]
  ax.step(v,flux,where='mid',color='#347cad',lw=.8,label='Native coadd');ax.plot(v,nm,color='#555555',ls='--',lw=1.0,label='H0: common frequencies');ax.plot(v,am,color='#ba4b47',lw=1.1,label='H1: 3 relative shifts');ax.axhline(1,color='gray',lw=.5);ax.set_ylim(-.12,1.12);ax.text(.02,.08,f'Fe II {k}',transform=ax.transAxes);ax.set_ylabel('Normalized flux');ax.grid(alpha=.16)
  rx.axhspan(-1,1,color='gray',alpha=.13);rx.axhline(0,color='gray',lw=.5);rx.step(v[good],(nm[good]-flux[good])/err[good],where='mid',color='#555555',ls='--',lw=.8);rx.step(v[good],(am[good]-flux[good])/err[good],where='mid',color='#ba4b47',lw=.8);rx.set_ylabel('(model − data) / error');rx.grid(alpha=.16)
 axes[0,0].legend(loc='upper right',fontsize=8);axes[-1,0].set_xlabel('Velocity at z = 2.659 (km/s)');axes[-1,1].set_xlabel('Velocity (km/s)');fig.suptitle('J064326−504112 failed-primary diagnostic: shifts do not repair weak 1611 residuals',fontsize=12);fig.tight_layout();fig.savefig(F/'failure_pair_comparison.pdf');fig.savefig(F/'failure_pair_comparison.png',dpi=170);plt.close(fig)
 text=['# J064326−504112: amended failure-case displacement diagnostic','', '**Adding three relative line shifts gives a limited objective improvement and does not repair the weak 1611 mismatch. The target remains outside the precision/common-displacement sample.**','', 'This is a root-authorized protocol amendment after the initial quality screen. The earlier adequacy gate decided whether a model was suitable for a precision displacement estimate; it was not a population-level null test. Omitting every inadequate H0 without checking H1 could hide genuine sensitivity to frequency changes. The present bounded comparison explicitly tests that possibility for this target and retains the result, without promoting it to a calibrated measurement.','', 'The amendment was recorded before the new fits in `protocol_amendment.json`. It preserves the original four lines (1608, 1611, 2374, 2382), all436 native pixels, the [−145,+100] km/s window,16 shared gas components, original expected-fluctuation diagonal weights and21 subpixel integration. The weak 1611 line is retained. There is no residual clipping or component reselection.','', '| Model | Parameters | Pixels | χ² | Nominal dof | Weak 1611 χ²/pixel |','|---|---:|---:|---:|---:|---:|',f"| Selected original H0 | {n['npar']} | {n['ndata']} | {n['chi2']:.9f} | {n['nominal_ndf']} | {n['per_line'][1]['chi2_per_pixel']:.9f} |",f"| H1, three relative shifts | {a['npar']} | {a['ndata']} | {a['chi2']:.9f} | {a['nominal_ndf']} | {a['per_line'][1]['chi2_per_pixel']:.9f} |",'',f"The improvement is Δχ² = **{s['delta_chi2']:.9f} for3 added parameters**. Both models still fail the same weak-line residual gate (χ²/pixel≤1.8). Allowing frequency offsets therefore does not repair this model failure within the frozen architecture and bounds. This is not an exhaustive test of every possible frequency-dependent effect, blended-line model or gas architecture.",'','The diagnostic H1 offsets relative to fixed2374 are:', '', '| Transition | Conditional best-fit offset (m/s) |','|---|---:|']
 for k,v in s['shifts_m_s'].items():text.append(f'| {k} | {v:+.6f} |')
 text += ['', 'These are nuisance-fit endpoints under an inadequate model. They have no reported precision uncertainty and are not alpha estimates or cosmic-age observations. In particular, the1611 shift is close to the−1000 m/s permitted edge, though it is not classified as an active shift bound. The largest localized weak-line residual remains conceptually different from shifting the entire weak profile.','', 'Only two new fits were run: H1 from the original primary H0 (45 evaluations, ftol stop), followed by H0 cross-started from H1 (36 evaluations, ftol stop). The cross-started H0 hasχ²=532.225296838 and does not beat the original H0; the predeclared optional extra H1 was therefore not triggered.','',f"H0 and H1 both retain active `logb_14` (lower0.5 km/s) and `zero_1611` (upper+0.02). Their recorded first-order optimalities are{n['stationarity']['scipy_optimality']:.6g} and{a['stationarity']['scipy_optimality']:.6g}. Successful ftol stopping does not establish strong stationarity or a global optimum.16 components is the upper end of the previously searched count grid.",'', 'All original20 fit JSON/NPZ files and the frozen primary configuration remain protected. The original gated-run reports describe that historical protocol; this separate amendment supplies the additional explanatory H1 result. The canonical primary status remains `not_estimated_primary_due_model_failure`. The present outcome cannot be described as a population null result.','', 'Reproducibility: `summary.json` points to the selected original H0 and new H1; new fit records and arrays are under `J064326-504112/`. `failure_pair_comparison.pdf` shows the same raw pixels, both models and residuals.']
 auditpath=F/'independent_review.json'
 if auditpath.exists():
  audit=load(auditpath);text+=['', f"Independent review passes {audit['checks_pass']}/{audit['checks_total']} grouped checks, including preservation of all 40 original fit files, objective and Jacobian replay, and 28 representative finite-difference columns including all three shifts. See `independent_review.md` and `independent_review.json`. Calculation verification does not establish physical validity."]
 final='\n'.join(text)+'\n'
 for aa,bb in [('all436','all 436'),('window,16','window, 16'),('and21','and 21'),('for3','for 3'),('fixed2374','fixed 2374'),('the1611','the 1611'),('the−1000','the −1000'),('hasχ²','has χ²'),('lower0.5','lower 0.5'),('upper+0.02','upper +0.02'),('are0.','are 0.'),('and0.','and 0.'),('optimum.16','optimum. 16'),('original20','original 20')]:final=final.replace(aa,bb)
 (F/'report.md').write_text(final)
 manifest={str(p.relative_to(F)):hashlib.sha256(p.read_bytes()).hexdigest() for p in F.rglob('*') if p.is_file() and p.name not in ['artifact_manifest.json','run.log']}
 (F/'artifact_manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
if __name__=='__main__':main()
